package com.smartexam.service;
import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl; import com.smartexam.entity.Answers; import com.smartexam.mapper.AnswersMapper; import org.springframework.stereotype.Service; import java.util.List;
@Service public class AnswersService extends ServiceImpl<AnswersMapper, Answers> { public List<Answers> findBySubmissionId(Long submissionId) { return baseMapper.selectBySubmissionId(submissionId); } public Answers findOne(Long submissionId,Long questionId){return baseMapper.selectOne(submissionId,questionId);} public java.util.Set<Long> pendingManualReviewSubmissionIds(Long examId){return new java.util.HashSet<>(baseMapper.selectPendingManualSubmissionIds(examId));} }
